SELECT budget_bucket, dept_name, budget_range FROM (SELECT CASE WHEN budget >= 3177000 THEN 'high' WHEN budget >= 1984000 THEN 'mid' ELSE 'low' END AS budget_bucket, dept_name, MAX(budget) - MIN(budget) AS budget_range FROM departments WHERE budget < 2339000 GROUP BY CASE WHEN budget >= 3177000 THEN 'high' WHEN budget >= 1984000 THEN 'mid' ELSE 'low' END, dept_name) AS sub WHERE budget_range >= 74 ORDER BY budget_range DESC, dept_name;
